#include <bits/stdc++.h>
using namespace std;
int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int W,H,n; if(!(cin>>W>>H>>n)) return 0;
    vector<array<int,4>> cuts(n);
    set<int> sx, sy; sx.insert(0); sx.insert(W); sy.insert(0); sy.insert(H);
    for(int i=0;i<n;i++){
        int x1,y1,x2,y2; cin>>x1>>y1>>x2>>y2;
        cuts[i]={x1,y1,x2,y2};
        sx.insert(x1); sx.insert(x2);
        sy.insert(y1); sy.insert(y2);
    }
    vector<int> xs(sx.begin(), sx.end()), ys(sy.begin(), sy.end());
    int m = (int)xs.size()-1; // aantal cellen in x-rjochting
    int ny = (int)ys.size()-1; // yn y-rjochting

    // map weardes nei indices
    auto idx = [](const vector<int>& v, int val){
        return (int)(lower_bound(v.begin(), v.end(), val) - v.begin());
    };

    // vertical_wall[k][j] = der is in muorre op vertical line xs[k] foar y-interval j (ús muorre foarkomt ferbining tusken cellen i=k-1 en i=k op rij j)
    vector<vector<bool>> vertical_wall(xs.size(), vector<bool>(ny, false));
    // horizontal_wall[k][i] = der is in muorre op horizontal line ys[k] foar x-interval i (foarkomt ferbining tusken cellen j=k-1 en j=k op kolom i)
    vector<vector<bool>> horizontal_wall(ys.size(), vector<bool>(m, false));

    // râne fan de bûtenkant as muorren
    for(int j=0;j<ny;j++){ vertical_wall[0][j]=true; vertical_wall[xs.size()-1][j]=true; }
    for(int i=0;i<m;i++){ horizontal_wall[0][i]=true; horizontal_wall[ys.size()-1][i]=true; }

    // ferwurkje brekken
    for(auto &c:cuts){
        int x1=c[0], y1=c[1], x2=c[2], y2=c[3];
        if(x1==x2){ // verticale brek op x = x1 tusken y1..y2
            int k = idx(xs, x1);
            int ya = min(y1,y2), yb = max(y1,y2);
            for(int j=0;j<ny;j++){
                if(ys[j] >= ya && ys[j+1] <= yb) vertical_wall[k][j]=true;
            }
        } else { // horizontale brek op y = y1 tusken x1..x2
            int k = idx(ys, y1);
            int xa = min(x1,x2), xb = max(x1,x2);
            for(int i=0;i<m;i++){
                if(xs[i] >= xa && xs[i+1] <= xb) horizontal_wall[k][i]=true;
            }
        }
    }

    vector<vector<char>> vis(m, vector<char>(ny, 0));
    vector<long long> areas;
    for(int i=0;i<m;i++){
        for(int j=0;j<ny;j++){
            if(vis[i][j]) continue;
            // BFS/DFS fan komponint
            long long sum = 0;
            stack<pair<int,int>> st; st.push({i,j}); vis[i][j]=1;
            while(!st.empty()){
                auto [cx, cy] = st.top(); st.pop();
                long long dx = xs[cx+1] - xs[cx];
                long long dy = ys[cy+1] - ys[cy];
                sum += dx*dy;
                // rjochts
                if(cx+1 < m){
                    // gestelde muorre op xs index cx+1
                    if(!vertical_wall[cx+1][cy] && !vis[cx+1][cy]){ vis[cx+1][cy]=1; st.push({cx+1,cy}); }
                }
                // lofts
                if(cx-1 >= 0){
                    if(!vertical_wall[cx][cy] && !vis[cx-1][cy]){ vis[cx-1][cy]=1; st.push({cx-1,cy}); }
                }
                // boppe (j+1)
                if(cy+1 < ny){
                    if(!horizontal_wall[cy+1][cx] && !vis[cx][cy+1]){ vis[cx][cy+1]=1; st.push({cx,cy+1}); }
                }
                // ûnder (j-1)
                if(cy-1 >= 0){
                    if(!horizontal_wall[cy][cx] && !vis[cx][cy-1]){ vis[cx][cy-1]=1; st.push({cx,cy-1}); }
                }
            }
            areas.push_back(sum);
        }
    }

    sort(areas.begin(), areas.end());
    for(size_t t=0;t<areas.size();++t){
        if(t) cout << ' ';
        cout << areas[t];
    }
    cout << '\n';
    return 0;
}

