#include <bits/stdc++.h>
using namespace std;
int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n; if(!(cin>>n)) return 0;
    struct Item{int x,y; long long t; double p;};
    vector<Item>a(n);
    for(int i=0;i<n;i++) cin>>a[i].x>>a[i].y>>a[i].t>>a[i].p;
    vector<int> idx(n); iota(idx.begin(), idx.end(), 0);
    sort(idx.begin(), idx.end(), [&](int i, int j){ if(a[i].t!=a[j].t) return a[i].t < a[j].t; return i<j; });
    vector<double> dp(n,0.0);
    const double EPS = 1e-9;
    double ans = 0.0;
    for(int ii=0; ii<n; ++ii){
        int j = idx[ii];
        dp[ii] = a[j].p; // as earste kinne wy derhinne begjinne
        for(int kk=0; kk<ii; ++kk){
            int i = idx[kk];
            long long dt = a[j].t - a[i].t;
            if(dt < 0) continue;
            double dx = a[j].x - a[i].x;
            double dy = a[j].y - a[i].y;
            double dist = sqrt(dx*dx + dy*dy);
            if(dist <= (double)dt + EPS){
                dp[ii] = max(dp[ii], dp[kk] + a[j].p);
            }
        }
        ans = max(ans, dp[ii]);
    }
    cout.setf(std::ios::fixed); cout<<setprecision(10)<<ans<<"\n";
    return 0;
}

