Oerbliuwsel en oplossingsidee

Dit is it bekende probleem "antal pearen knopen yn in beam mei ôfstân k". In effisjinte en normale oanpak is centroid-dekomposysje. Ynkoarten: selektearje it centroid fan de hjoeddeistige beam (of subbeam), telt alle pearen dy't passearje troch dat centroid en hawwe ôfstân k, wylst jo de bydragen fan elke subbeam apart sammelje en kombinearje mei in frekwinsjetabel fan depths. Dan splitsje jo rekursyf op elke subbeam (negearje it centroid) en gean troch. De kompleksiteit is rûchwei O(n log n) mei k-beheining by it sammeljen (en dochs O(n log n) praktysk, foar k ≤ 500 is it hiel goed).

Algemiene stappen
- Bou de adjacency-list foar de beam.
- Skriuw funksjes om subtree-grutte te bepalen en it centroid te finen.
- Foar it centroid: foar elk buordsûbtree krije in list fan depths (ôfstannen fan it centroid) oant k. Foar elke depth d telle wy hoeveel yn earder ferwurke subtrees hawwe depth k - d (dat jout nij pearen). Nei it ferwurkjen fan in subtree foegje wy syn depths ta yn de frekwinsjetabel.
- Markearje it centroid as besocht en dekomposearje rekursyf.

Kompleksiteit: O(n log n) (praktysk goed foar n ≤ 50000, k ≤ 500)

C++-implemintaasje (meitsje sûnder %lld, brûk cin/cout):

#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int n, K;
vector<vector<int>> g;
vector<int> subsize;
vector<bool> used;
ll answer = 0;

void dfs_size(int u, int p) {
    subsize[u] = 1;
    for (int v : g[u]) if (v != p && !used[v]) {
        dfs_size(v, u);
        subsize[u] += subsize[v];
    }
}

int dfs_centroid(int u, int p, int total) {
    for (int v : g[u]) if (v != p && !used[v]) {
        if (subsize[v] > total / 2) return dfs_centroid(v, u, total);
    }
    return u;
}

void collect_depths(int u, int p, int d, vector<int> &depths) {
    if (d > K) return; // hoefolle djipper as K net nuttich
    depths.push_back(d);
    for (int v : g[u]) if (v != p && !used[v]) {
        collect_depths(v, u, d + 1, depths);
    }
}

void decompose(int entry) {
    dfs_size(entry, -1);
    int c = dfs_centroid(entry, -1, subsize[entry]);
    used[c] = true;

    vector<int> cnt(K + 1, 0);
    cnt[0] = 1; // paat dat begjint op it centroid sel

    for (int v : g[c]) if (!used[v]) {
        vector<int> depths;
        collect_depths(v, c, 1, depths);
        // tel pearen tusken dizze subtree en earder ferwurke subtrees
        for (int d : depths) {
            if (d <= K) answer += cnt[K - d];
        }
        // foegje dizze depths ta yn cnt
        for (int d : depths) if (d <= K) cnt[d]++;
    }

    // rekursyf op elke buordsûbtree
    for (int v : g[c]) if (!used[v]) decompose(v);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> n >> K)) return 0;
    g.assign(n + 1, {});
    for (int i = 0; i < n - 1; ++i) {
        int a, b; cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    subsize.assign(n + 1, 0);
    used.assign(n + 1, false);

    decompose(1);

    cout << answer << '\n';
    return 0;
}

Opmerkingen
- De koade brûkt 1-basearre knopen (neffens de ynput). Wurket foar grutte n en K oant 500.
- As K grutter wie, soe men noch ekstra filtere moatte by depths; no blokkearje wy depths > K op sammeljen, dus it bliuwt effisjint.

