Hjir is in ienfâldich Python-programma dat it beskreaune formatearjen fan INI-bestannen útfiert. It lêst fan stdin (earste rigel n, folge troch n rigels), negeart opmerkingen en lege rigels, gearfettet sekjes mei deselde namme, lit by-key de lêste foarkommende wearde stean, en print it resultaat mei globale kaai-wearde-rigels earst, dan sekjes yn alfabetyske folchoarder; binnen elke groep binne rigels sorteare op kaai.

#!/usr/bin/env python3
import sys

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    try:
        n = int(data[0].strip())
    except:
        return
    lines = data[1:1+n]

    sections = {}  # map section_name -> dict(key->value)
    global_section = {}
    cur = None  # None means global

    for line in lines:
        # determine first non-space char
        stripped_leading = line.lstrip()
        if not stripped_leading:
            # lege rigel -> negearre
            continue
        if stripped_leading[0] == ';':
            # kommentaarrigel -> negearre
            continue
        sline = line.strip()
        # is it in-seksje rigel?
        if sline.startswith('[') and sline.endswith(']'):
            name = sline[1:-1].strip()
            if name not in sections:
                sections[name] = {}
            cur = name
            continue
        # oars moatte it key=value rigels wêze
        if '=' in line:
            idx = line.find('=')
            key = line[:idx].strip()
            val = line[idx+1:].strip()
            if cur is None:
                # global
                global_section[key] = val
            else:
                sections[cur][key] = val
        # oars: negearre (net-standert rigel)

    out_lines = []
    # earst globale kaai-wearde rigels, sorteare op kaai
    for k in sorted(global_section.keys()):
        out_lines.append(f"{k}={global_section[k]}")

    # dan sekjes yn alfabetyske folchoarder
    for sec in sorted(sections.keys()):
        out_lines.append(f"[{sec}]")
        for k in sorted(sections[sec].keys()):
            out_lines.append(f"{k}={sections[sec][k]}")

    sys.stdout.write('\n'.join(out_lines))

if __name__ == '__main__':
    main()

