#include <bits/stdc++.h>
using namespace std;
int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n; int m;
    if(!(cin>>n>>m)) return 0;
    vector<pair<long long,long long>> v; // (bi, ai)
    for(int i=0;i<m;++i){
        long long a,b; cin>>a>>b;
        v.emplace_back(b,a);
    }
    sort(v.begin(), v.end(), greater<>());
    long long reste = n;
    long long ans = 0;
    for(auto &p: v){
        if(reste==0) break;
        long long bi = p.first;
        long long ai = p.second;
        long long take = min(ai, reste);
        ans += take * bi;
        reste -= take;
    }
    cout<<ans<<"\n";
    return 0;
}

