import sys

def main():
    max_X = 10**6
    INF = float('inf')
    dp = [INF] * (max_X + 1)
    dp[0] = 0
    primes = [2, 3, 5, 7]

    for x in range(1, max_X + 1):
        for p in primes:
            if x >= p and dp[x - p] + 1 < dp[x]:
                dp[x] = dp[x - p] + 1

    T = int(sys.stdin.readline())
    for _ in range(T):
        X = int(sys.stdin.readline())
        if dp[X] == INF:
            print(-1)
        else:
            print(dp[X])

if __name__ == '__main__':
    main()
```

